document.addEventListener("DOMContentLoaded",()=>{const e=document.querySelectorAll(".metric-value"),t=new IntersectionObserver((e,t)=>{e.forEach(e=>{e.isIntersecting&&((e=>{const t=+e.getAttribute("data-target"),r=1e3/60,n=Math.round(119.99999999999999);let o=0;const a=setInterval(()=>{o++;const r=o/n,c=1-Math.pow(1-r,3),s=Math.floor(c*t);e.innerText=s.toLocaleString(),o===n&&(e.innerText=t.toLocaleString(),clearInterval(a))},r)})(e.target),t.unobserve(e.target))})},{threshold:.3});e.forEach(e=>t.observe(e))});